import pandas as pd

class Solution:
    def grand_slam_titles(self, players: pd.DataFrame, championships: pd.DataFrame) -> pd.DataFrame:
        cols = ['Wimbledon', 'Fr_open', 'US_open', 'Au_open']
        rows = []
        for _, p in players.iterrows():
            cnt = int(sum((championships[c] == p.player_id).sum() for c in cols))
            if cnt:
                rows.append([int(p.player_id), p.player_name, cnt])
        return pd.DataFrame(rows, columns=['player_id', 'player_name', 'grand_slams_count'])

