#include <bits/stdc++.h>
struct Player { int playerId; std::string playerName; };

class Solution {
public:
    std::vector<std::tuple<int, std::string, int>> grandSlamTitles(
            std::vector<Player>& players, std::vector<std::array<int, 4>>& championships) {
        std::vector<std::tuple<int, std::string, int>> res;
        for (auto& p : players) {
            int cnt = 0;
            for (auto& row : championships)
                for (int pid : row)
                    cnt += (pid == p.playerId);
            if (cnt > 0)
                res.emplace_back(p.playerId, p.playerName, cnt);
        }
        return res;
    }
};

