class Solution {
    static class Player { int playerId; String playerName;
        Player(int id, String name) { playerId = id; playerName = name; } }

    public List<Object[]> grandSlamTitles(List<Player> players, List<int[]> championships) {
        Map<Integer, Integer> titles = new HashMap<>();
        for (int[] row : championships)
            for (int pid : row)
                titles.merge(pid, 1, Integer::sum);
        List<Object[]> res = new ArrayList<>();
        for (Player p : players) {
            Integer c = titles.get(p.playerId);
            if (c != null) res.add(new Object[]{p.playerId, p.playerName, c});
        }
        return res;
    }
}

