var grandSlamTitles = function(players, championships) {
    const titles = new Map();
    for (const row of championships)
        for (const pid of row)
            titles.set(pid, (titles.get(pid) || 0) + 1);
    return players
        .filter(p => titles.has(p.playerId))
        .map(p => [p.playerId, p.playerName, titles.get(p.playerId)]);
};
